CREATE TABLE tenant_onboarding(tenant_id uuid PRIMARY KEY REFERENCES tenants(id) ON DELETE CASCADE,current_step text NOT NULL DEFAULT 'BUSINESS_PROFILE',completed boolean NOT NULL DEFAULT false,data jsonb NOT NULL DEFAULT '{}'::jsonb,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE saas_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE,name text NOT NULL,monthly_price_minor bigint NOT NULL DEFAULT 0 CHECK(monthly_price_minor>=0),currency text NOT NULL DEFAULT 'MYR',entitlements jsonb NOT NULL DEFAULT '{}'::jsonb,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
DO $$ BEGIN CREATE TYPE wsb_subscription_status AS ENUM('TRIAL','ACTIVE','PAST_DUE','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE tenant_subscriptions(tenant_id uuid PRIMARY KEY REFERENCES tenants(id) ON DELETE CASCADE,plan_code text NOT NULL REFERENCES saas_plans(code),status wsb_subscription_status NOT NULL DEFAULT 'TRIAL',trial_ends_at timestamptz,current_period_ends_at timestamptz,cancel_at_period_end boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tenant_usage_counters(tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,usage_key text NOT NULL,period_key text NOT NULL,amount bigint NOT NULL DEFAULT 0 CHECK(amount>=0),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,usage_key,period_key));
CREATE TABLE ai_model_prices(provider text NOT NULL,model text NOT NULL,input_micros_per_million bigint NOT NULL DEFAULT 0,output_micros_per_million bigint NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(provider,model));
